package fr.hydrosea.comptage.infrastructure;import static fr.hydrosea.comptage.application.ModelesComptage.*;import fr.hydrosea.commun.application.RegleMetierException;import fr.hydrosea.commun.application.VersionObsoleteException;import fr.hydrosea.comptage.application.PortComptage;import java.math.BigDecimal;import java.util.List;import java.util.UUID;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;
@Repository public class AdaptateurJdbcComptage implements PortComptage{private final JdbcTemplate jdbc;public AdaptateurJdbcComptage(JdbcTemplate jdbc){this.jdbc=jdbc;}private static final org.springframework.jdbc.core.RowMapper<VueCompteur> COMPTEUR=(r,n)->new VueCompteur(r.getObject("id",UUID.class),r.getString("numero_serie"),r.getString("fabricant"),r.getString("modele"),(Integer)r.getObject("calibre"),r.getString("statut"),r.getInt("version"));private static final org.springframework.jdbc.core.RowMapper<VueAffectation> AFFECTATION=(r,n)->new VueAffectation(r.getObject("id",UUID.class),r.getObject("compteur_id",UUID.class),r.getObject("point_consommation_id",UUID.class),r.getObject("index_pose",BigDecimal.class),r.getString("reference_intervention"));public List<VueCompteur> listerCompteurs(){return jdbc.query("SELECT id,numero_serie,fabricant,modele,calibre,statut,version FROM cpt.compteur WHERE date_suppression IS NULL ORDER BY date_creation DESC LIMIT 100",COMPTEUR);}public VueCompteur obtenirCompteur(UUID id){return jdbc.queryForObject("SELECT id,numero_serie,fabricant,modele,calibre,statut,version FROM cpt.compteur WHERE id=?",COMPTEUR,id);}public VueCompteur creer(UUID id,CommandeCreerCompteur c){jdbc.update("INSERT INTO cpt.compteur(id,numero_serie,fabricant,modele,calibre) VALUES (?,?,?,?,?)",id,c.numeroSerie().strip().toUpperCase(),c.fabricant(),c.modele(),c.calibre());return obtenirCompteur(id);}public VueCompteur modifier(UUID id,int version,CommandeModifierCompteur c){if(jdbc.update("UPDATE cpt.compteur SET fabricant=COALESCE(?,fabricant),modele=COALESCE(?,modele),calibre=COALESCE(?,calibre),version=version+1,date_modification=now() WHERE id=? AND version=?",c.fabricant(),c.modele(),c.calibre(),id,version)==0)throw new VersionObsoleteException();return obtenirCompteur(id);}public VueAffectation poser(UUID id,int version,CommandePoserCompteur c){Integer n=jdbc.queryForObject("SELECT count(*) FROM des.point_consommation WHERE id=?",Integer.class,c.point());if(n==null||n==0)throw new RegleMetierException("Point de consommation absent.");if(jdbc.update("UPDATE cpt.compteur SET statut='POSE',version=version+1 WHERE id=? AND version=? AND statut='DISPONIBLE'",id,version)==0)throw new VersionObsoleteException();UUID affectation=UUID.randomUUID();jdbc.update("INSERT INTO cpt.affectation_compteur(id,compteur_id,point_consommation_id,periode,index_pose,reference_intervention) VALUES (?,?,?,tstzrange(?,NULL,'[)'),?,?)",affectation,id,c.point(),c.date(),c.index(),c.intervention());return obtenirAffectation(affectation);}public List<VueAffectation> listerAffectations(){return jdbc.query("SELECT id,compteur_id,point_consommation_id,index_pose,reference_intervention FROM cpt.affectation_compteur WHERE date_suppression IS NULL ORDER BY date_creation DESC LIMIT 100",AFFECTATION);}public VueAffectation obtenirAffectation(UUID id){return jdbc.queryForObject("SELECT id,compteur_id,point_consommation_id,index_pose,reference_intervention FROM cpt.affectation_compteur WHERE id=?",AFFECTATION,id);}}
